def transform(g):
    from collections import Counter
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    cells={}
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg: cells.setdefault(g[r][c],[]).append((r,c))
    a,b=sorted(cells,key=lambda k:len(cells[k]))
    mino,runcolor=a,b
    runpts=cells[runcolor]; mpts=cells[mino]
    rows=sorted(set(r for r,c in runpts)); cols=sorted(set(c for r,c in runpts))
    vertical = len(cols)<len(rows)  # vertical run: single column
    # build two segments along the run axis
    if vertical:
        fix=cols[0]; axis=sorted(r for r,c in runpts)
    else:
        fix=rows[0]; axis=sorted(c for r,c in runpts)
    segs=[]; cur=[axis[0]]
    for x in axis[1:]:
        if x==cur[-1]+1: cur.append(x)
        else: segs.append(cur); cur=[x]
    segs.append(cur)
    assert len(segs)==2, segs
    out=[row[:] for row in g]
    def beam(start,dr,dc):
        r,c=start
        while True:
            r,c=r+dr,c+dc
            if not(0<=r<H and 0<=c<W): return
            v=out[r][c]
            if v==mino: out[r][c]=4; return
            if v!=bg: return
            out[r][c]=mino
    # anchors: first cell of each segment
    anch=[(segs[0][0],fix),(segs[1][0],fix)] if vertical else [(fix,segs[0][0]),(fix,segs[1][0])]
    daxis = anch[1][0 if vertical else 1]-anch[0][0 if vertical else 1]  # displacement seg0->seg1 along run axis
    mlines = sorted(set(r for r,c in mpts)) if vertical else sorted(set(c for r,c in mpts))
    for m in mlines:
        ci = 0 if segs[0][0]<=m<=segs[0][-1] else 1
        s=segs[ci]; s2=segs[1-ci]
        fixo = anch[1-ci][1 if vertical else 0]  # other run's fixed coordinate
        # direction for each run: toward other run's fixed coordinate
        def direction(fixed_coord, other_fixed):
            if vertical: return (0, 1 if other_fixed>fixed_coord else -1)
            return (1 if other_fixed>fixed_coord else -1, 0)
        # containing run emits at m
        dr,dc=direction(fix, anch[1-ci][1 if vertical else 0])
        beam((m,fix) if vertical else (fix,m), dr,dc)
        # other run emits at displaced line
        m2 = m - daxis*(1 if ci==0 else -1)
        if min(s2)<=m2<=max(s2):
            dr,dc=direction(anch[1-ci][1 if vertical else 0], fix)
            beam((m2,fix) if vertical else (fix,m2), dr,dc) if vertical else beam((fix,m2),dr,dc)
    return out

