                if p in runpts: runpts.discard(p); stack.append(p)
        comps.append(comp)
    assert len(comps)==2
    runs=[]
    for comp in comps:
        rs=[r for r,c in comp]; cs=[c for r,c in comp]
        vertical = len(set(cs))==1
        if vertical: runs.append({'vert':True,'col':cs[0],'lo':min(rs),'hi':max(rs),'start':min(rs)})
        else: runs.append({'vert':False,'row':rs[0],'lo':min(cs),'hi':max(cs),'start':min(cs)})
    out=[row[:] for row in g]
    def beam(start,dr,dc):
        r,c=start
        while True:
