            if not(0<=r<H and 0<=c<W): return
            v=out[r][c]
            if v==mino: out[r][c]=4; return
            if v!=bg: return
            out[r][c]=mino
    v0=runs[0]['vert']
    mlines = sorted(set(r for r,c in mpts)) if v0 else sorted(set(c for r,c in mpts))
    for m in mlines:
        ci = next(i for i,ru in enumerate(runs) if ru['lo']<=m<=ru['hi'])
        me,other=runs[ci],runs[1-ci]
        disp = other['start']-me['start']  # along run axis
        def emit(ru,line):
            if not (ru['lo']<=line<=ru['hi']): return
            if ru['vert']:
                dc = 1 if other['col']>ru['col'] else -1
                beam((line,ru['col']),0,dc)
            else:
                dr = 1 if other['row']>ru['row'] else -1
                beam((ru['row'],line),dr,0)
        emit(me,m)
        emit(other,m+disp)
    return out

